# Prop build spec for Ashen Abyss. Each row: dict(name, src, ...) consumed by mdl_build.py
#  objs   regex (re.search) selecting source objects (None = all meshes)
#  tris   triangle budget (decimated only when above it)
#  tex    max texture edge in px
#  cat    tree | rock | plant | breakable | light | furniture | container | structure | clutter
#  zones  list of zone tags
#  drop   regex of material names whose faces are deleted (leaves, twigs ...)
#  scale  uniform factor or (x,y,z);  up='longest' rotates the longest bbox axis to +Z first;  height=h rescales to h metres
#  tint   RGB multiplier applied to the base-colour texture
#  ground 'min' (lowest point on the floor) | 'auto' (natural scans: keep authored ground or sink 12 %) | 'top' (hanging, origin at top) | 'keep'
#  parts  {node_name: (regex, pivot)} kept as separate mesh nodes (pivot: back_bottom | left | right)
#  flame  'mat:<re>' (delete faces, one flame per island) | 'matc:<re>' (keep, per island) | 'mata:<re>' (keep, average) | 'obj:<re>' | 'top:<dz>'
#  mask   True -> alpha-tested foliage (alphaMode MASK)
#  cap    dict(kind='snow'|'moss', lo, hi, ...) -> bake a snow / moss layer onto up-facing surfaces (albedo + flattened normal map)
ALL = ["town", "wastes", "crypt", "abyss", "frost", "mire", "sands", "sanctum"]
SNOW = dict(kind="snow", lo=0.30, hi=0.72, color=(0.74, 0.76, 0.80))        # close to the snow_fresh / snow_trampled terrain sets
SNOW_TOP = dict(kind="snow", lo=0.62, hi=0.94, color=(0.74, 0.76, 0.80))    # flat tops only (stumps)
MOSS = dict(kind="moss", lo=0.12, hi=0.66, tex="moss", darken=0.68, desat=0.3)
MOSS_TOP = dict(kind="moss", lo=0.50, hi=0.92, tex="moss", darken=0.68, desat=0.3)
OUT = ["town", "wastes", "frost", "mire", "sands"]


def P(name, src, cat, zones, tris=3000, tex=1024, **kw):
    d = dict(name=name, src=src, cat=cat, zones=zones, tris=tris, tex=tex)
    d.update(kw)
    return d


